-- PT110-S2-Q5. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT110-S2-Q5$batch03$ AND q.stimulus=$batch03$Many elementary schools have recently offered computer-assisted educational programs. Students’ reactions after several years have been decidedly mixed. Whereas students have found computers very useful in studying arithmetic, they have found them of little help in studying science, and of no help at all with their reading and writing skills.$batch03$ AND q.prompt=$batch03$Which one of the following, if true, most helps to explain the students' mixed reactions?$batch03$ AND q.correct_choice=$batch03$B$batch03$) THEN RAISE EXCEPTION 'Question changed: PT110-S2-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT110-S2-Q5$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT110-S2-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT110-S2-Q5$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Schools offered computer-assisted programs to students.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$Students found them very useful for arithmetic, of little help in science, and no help in reading and writing?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$The same computers produced different results by subject. So the answer has to be something about the subjects. What does arithmetic have that computers suit and reading and writing lack? Clear right-or-wrong answers that a program can check.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Find a feature of arithmetic that makes it better suited to computers than the other subjects.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT110-S2-Q5$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$Students started both reading and arithmetic before computers. That applies to two of the subjects alike, so it cannot explain the split.$batch03$), ($batch03$B$batch03$, $batch03$Arithmetic's exactness makes it the best fit for computer-assisted learning. That gives a subject-level difference that matches the ranking: arithmetic most useful, the others less.$batch03$), ($batch03$C$batch03$, $batch03$Teacher reluctance would affect every subject. It does not explain why one subject did well and the others did not.$batch03$), ($batch03$D$batch03$, $batch03$Interest in the newest computers applies to all programs equally.$batch03$), ($batch03$E$batch03$, $batch03$More programs in reading and writing should have made computers *more* helpful there, not less.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT110-S2-Q5$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
